{
  "sop_id": "SOP-015",
  "title": "Invoice Verification",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create and assign ticket",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Check vendor GSTIN and PAN",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Verify invoice is not a duplicate (same vendor + invoice no. + amount)",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Perform three-way match (invoice vs PO vs GRN, line by line)",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Calculate GST input credit and TDS",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Deduct advances or other deductions",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S7",
      "name": "Prepare payment voucher",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S8",
      "name": "Submit payment voucher",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1",
      "name": "Wait for Stores/Operations confirmation (GRN or completion certificate)",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1_provider",
      "name": "Stores/Operations confirmation",
      "role": "External",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge verification and approval",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "A2",
      "name": "Lead approval (if invoice is outside tolerance or > 10 lakh)",
      "role": "Lead",
      "type": "approval"
    },
    {
      "step_id": "A3",
      "name": "Documentation of exchange rate (for foreign-currency invoices)",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "R1",
      "name": "Correct and resubmit after rejection",
      "role": "Executor",
      "type": "rework"
    },
    {
      "step_id": "R2",
      "name": "Escalation to Lead after second rejection",
      "role": "Lead",
      "type": "approval"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "if invoice is outside tolerance (price more than 2% off, or any quantity variance) OR if invoice is above 10 lakh"
    },
    {
      "stage": "Lead",
      "condition": "after second rejection"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Stores/Operations",
      "item": "Confirmation of GRN or completion certificate",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Amount mismatch",
    "Wrong quantity",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.90
}
